#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "cJSON.h"
#include "lodepng.h"

static double *load_matrix(cJSON *root, const char *key, int *rows, int *cols) {
  cJSON *obj = cJSON_GetObjectItem(root, key);
  cJSON *shape = cJSON_GetObjectItem(obj, "shape");
  cJSON *data = cJSON_GetObjectItem(obj, "data");
  *rows = (int)cJSON_GetArrayItem(shape, 0)->valuedouble;
  *cols = (int)cJSON_GetArrayItem(shape, 1)->valuedouble;
  double *m = (double *)malloc(sizeof(double) * (*rows) * (*cols));
  int i = 0;
  cJSON *v;
  cJSON_ArrayForEach(v, data) m[i++] = v->valuedouble;
  return m;
}

static void matvec(const double *m, int rows, int cols, const double *x, double *y) {
  int r, c;
  for (r = 0; r < rows; r++) {
    y[r] = 0.0;
    for (c = 0; c < cols; c++) y[r] += m[r * cols + c] * x[c];
  }
}

int main(int argc, char **argv) {
  if (argc != 3) { fprintf(stderr, "usage: %s weights.json image.png\n", argv[0]); return 1; }

  FILE *f = fopen(argv[1], "rb");
  if (!f) { fprintf(stderr, "cannot open weights\n"); return 1; }
  fseek(f, 0, SEEK_END); long len = ftell(f); fseek(f, 0, SEEK_SET);
  char *buf = (char *)malloc(len + 1); fread(buf, 1, len, f); buf[len] = 0; fclose(f);

  cJSON *root = cJSON_Parse(buf);
  if (!root) { fprintf(stderr, "bad json\n"); return 1; }

  int in_r, in_c, hid_r, hid_c, out_r, out_c;
  double *w1 = load_matrix(root, "input_layer.weight", &in_r, &in_c);
  double *b1 = load_matrix(root, "input_layer.bias", &in_r, &in_c);
  double *w2 = load_matrix(root, "hidden_layer.weight", &hid_r, &hid_c);
  double *b2 = load_matrix(root, "hidden_layer.bias", &hid_r, &hid_c);
  double *w3 = load_matrix(root, "output_layer.weight", &out_r, &out_c);
  double *b3 = load_matrix(root, "output_layer.bias", &out_r, &out_c);

  unsigned char *img = 0;
  unsigned iw, ih;
  unsigned err = lodepng_decode32_file(&img, &iw, &ih, argv[2]);
  if (err) { fprintf(stderr, "png error %u\n", err); return 1; }

  int n = (int)(iw * ih);
  double *x = (double *)malloc(sizeof(double) * n);
  int i;
  for (i = 0; i < n; i++) x[i] = img[i * 4] / 255.0;

  double *h1 = (double *)malloc(sizeof(double) * in_r);
  double *h2 = (double *)malloc(sizeof(double) * hid_r);
  double *y  = (double *)malloc(sizeof(double) * out_r);

  matvec(w1, in_r, in_c, x, h1);  for (i = 0; i < in_r; i++)  h1[i] += b1[i]; for (i = 0; i < in_r; i++)  if (h1[i] < 0) h1[i] = 0;
  matvec(w2, hid_r, in_r, h1, h2); for (i = 0; i < hid_r; i++) h2[i] += b2[i]; for (i = 0; i < hid_r; i++) if (h2[i] < 0) h2[i] = 0;
  matvec(w3, out_r, hid_r, h2, y); for (i = 0; i < out_r; i++) y[i] += b3[i];

  int best = 0; double bestv = y[0];
  for (i = 1; i < out_r; i++) if (y[i] > bestv) { bestv = y[i]; best = i; }

  printf("%d\n", best);
  FILE *out = fopen("prediction.txt", "w");
  if (out) { fprintf(out, "%d\n", best); fclose(out); }

  return 0;
}
